"""Generate the website's offline benchmark registry from package data."""

from __future__ import annotations

import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    registry = json.loads(
        (ROOT / "src/agent_hour_tracker/benchmarks.json").read_text(encoding="utf-8")
    )
    content = (
        "// Generated by scripts/sync_benchmarks.py; edit the package registry.\n"
        "globalThis.AGENT_HOURS_BENCHMARKS = "
        + json.dumps(registry, indent=2, ensure_ascii=True)
        + ";\n"
    )
    target = ROOT / "site/benchmarks-data.js"
    if args.check:
        if not target.exists() or target.read_text(encoding="utf-8") != content:
            parser.exit(1, "Website benchmark data is stale. Run scripts/sync_benchmarks.py.\n")
    else:
        target.write_text(content, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
